function redact(object, keys) {
  const copy = { ...object };
  for (const key of keys) {
    if (key in copy) copy[key] = "[redacted]";
  }
  return copy;
}

const account = { owner: "Ada", balanceKobo: 500000, apiToken: "sk_test_51H8", pin: "4321" };
console.log(redact(account, ["apiToken", "pin"]));
console.log(account.pin);

