async function describeResponse(res) {
  const body = await res.text();
  return `${res.status} ${res.headers.get("content-type")}: ${body.slice(0, 20)}`;
}

const html = new Response("<!doctype html><h1>Page not found</h1>", {
  status: 404,
  headers: { "content-type": "text/html" },
});
console.log(await describeResponse(html));
const json = new Response('[{"sku":"RICE-5"}]', { status: 200, headers: { "content-type": "application/json" } });
console.log(await describeResponse(json));
